// Reproduces crates/deck-remote/tests/vectors/api-v1.json (generated by Rust
// crates/deck-remote/tests/api.rs): record bytes both ways, canonical request JSON, and the
// gateway JSON messages through the runtime validators.

import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';

import {
  ApiDecodeError,
  ApiRequestError,
  checkFeed,
  checkRequest,
  decodeEvent,
  decodeReply,
  decodeTermEnd,
  decodeWelcome,
  OP_NAMES,
  type Feed,
  type Op,
  opAllowed,
  opClass,
  opJournaled,
  PROTOCOL,
  type Request,
  RequestBuilder,
  requestJson,
  requestRecord,
} from '../src/remote/api.ts';
import { concat, fromHex, toHex, utf8 } from '../src/remote/bytes.ts';
import {
  type AppRecord,
  decodeRecords,
  encodeRecords,
  type Origin,
  RecordError,
  type RecordErrorCode,
} from '../src/remote/records.ts';

interface VectorRecord {
  kind: AppRecord['kind'];
  json?: string;
  hex?: string;
  messages?: number;
  view?: number;
  ctrl_c?: boolean;
  last?: boolean;
  cols?: number;
  rows?: number;
}

interface ApiVectors {
  protocol: number;
  records: { case: string; origin: Origin; hex: string; records: VectorRecord[] }[];
  rejected_records: {
    case: string;
    origin: Origin;
    hex: string;
    pad?: { byte: number; count: number };
    error: RecordErrorCode;
  }[];
  messages: { type: 'request' | 'reply' | 'event' | 'welcome' | 'term_end'; case: string; json: string }[];
  rejected_requests: { case: string; json: string; error: string; id?: number }[];
  skipped_records: { case: string; origin: Origin; hex: string; records: VectorRecord[] }[];
}

// A fixture checked into this repository; every test below fails on a shape mismatch.
const vectors: ApiVectors = JSON.parse(
  readFileSync(new URL('../../crates/deck-remote/tests/vectors/api-v1.json', import.meta.url), 'utf8'),
);

function toRecord(v: VectorRecord): AppRecord {
  const json = utf8(v.json ?? '');
  const bytes = fromHex(v.hex ?? '');
  const view = v.view ?? -1;
  switch (v.kind) {
    case 'request':
    case 'welcome':
    case 'reply':
    case 'event':
      return { kind: v.kind, body: json };
    case 'ack':
      return { kind: 'ack', messages: v.messages! };
    case 'input':
      return { kind: 'input', view, ctrlC: v.ctrl_c!, bytes };
    case 'resize':
    case 't_resize':
      return { kind: v.kind, view, cols: v.cols!, rows: v.rows! };
    case 't_snapshot':
      return { kind: 't_snapshot', view, last: v.last!, bytes };
    case 't_output':
      return { kind: 't_output', view, bytes };
    case 't_end':
      return { kind: 't_end', view, end: json };
  }
}

test('protocol version', () => {
  expect(vectors.protocol).toBe(PROTOCOL);
});

describe('records', () => {
  for (const vector of vectors.records) {
    test(vector.case, () => {
      const expected = vector.records.map(toRecord);
      expect(decodeRecords(fromHex(vector.hex), vector.origin)).toEqual(expected);
      expect(toHex(encodeRecords(expected))).toBe(vector.hex);
    });
  }

  // Unknown gateway-range kinds are skipped: decode only, there is nothing to encode.
  for (const vector of vectors.skipped_records) {
    test(`skips ${vector.case}`, () => {
      expect(decodeRecords(fromHex(vector.hex), vector.origin)).toEqual(vector.records.map(toRecord));
    });
  }

  for (const vector of vectors.rejected_records) {
    test(`rejects ${vector.case}`, () => {
      const pad = vector.pad === undefined ? new Uint8Array(0) : new Uint8Array(vector.pad.count).fill(vector.pad.byte);
      let caught: unknown;
      try {
        decodeRecords(concat(fromHex(vector.hex), pad), vector.origin);
      } catch (error) {
        caught = error;
      }
      expect(caught).toBeInstanceOf(RecordError);
      expect(caught instanceof RecordError ? caught.code : undefined).toBe(vector.error);
    });
  }
});

function messages(type: ApiVectors['messages'][number]['type']): ApiVectors['messages'] {
  return vectors.messages.filter((m) => m.type === type);
}

describe('requests encode canonically', () => {
  const requests = messages('request');

  for (const vector of requests) {
    test(vector.case, () => {
      const request: Request = JSON.parse(vector.json);
      expect(requestJson(request)).toBe(vector.json);
      const record = requestRecord(request);
      expect(record.kind).toBe('request');
      expect(record.kind === 'request' ? record.body : null).toEqual(utf8(vector.json));
      // The seq rule holds for every vector.
      expect(request.seq !== null && request.seq !== undefined).toBe(opJournaled(request.op));
    });
  }

  test('every op is covered', () => {
    const parsed: Request[] = requests.map((m) => JSON.parse(m.json));
    const covered = new Set(parsed.map((request) => request.op.op));
    expect([...covered].sort()).toEqual([...OP_NAMES].sort());
  });

  test('absent optionals are written as null, fields in Rust order', () => {
    const live = { generation: 2, key: 'k' };
    const op: Op = { op: 'switch_model', selector: 'x', live };
    expect(requestJson({ id: 1, seq: 4, op })).toBe(
      '{"id":1,"seq":4,"op":{"op":"switch_model","live":{"key":"k","generation":2},"selector":"x","level":null}}',
    );
    expect(requestJson({ id: 2, op: { op: 'subscribe', feed: { tail: 5, session: 's', feed: 'transcript' } } })).toBe(
      '{"id":2,"seq":null,"op":{"op":"subscribe","feed":{"feed":"transcript","session":"s","agent":null,"tail":5}}}',
    );
    expect(requestJson({ id: 3, seq: 5, op: { op: 'action', live, action: { mode: 'soft', type: 'compact' } } })).toBe(
      '{"id":3,"seq":5,"op":{"op":"action","live":{"key":"k","generation":2},"action":{"type":"compact","mode":"soft","focus":null}}}',
    );
  });
});

describe('class table and builder', () => {
  const live = { key: 'k', generation: 1 };

  test('classes, journaling and permissions', () => {
    expect(opClass({ op: 'attach', live, mode: 'observe' })).toBe('view');
    expect(opClass({ op: 'attach', live, mode: 'input' })).toBe('control');
    expect(opJournaled({ op: 'attach', live, mode: 'control' })).toBe(false);
    expect(opJournaled({ op: 'detach', view: 1 })).toBe(false);
    expect(opJournaled({ op: 'cancel', seq: 1 })).toBe(true);
    expect(opClass({ op: 'delete_sessions', sessions: [] })).toBe('manage');
    const viewOnly = { control: false, manage: false };
    const control = { control: true, manage: false };
    expect(opAllowed({ op: 'kill', live }, viewOnly)).toBe(false);
    expect(opAllowed({ op: 'kill', live }, control)).toBe(true);
    expect(opAllowed({ op: 'discard', project: 'p', files: [] }, control)).toBe(false);
    expect(opAllowed({ op: 'ping' }, viewOnly)).toBe(true);
  });

  test('feed bounds mirror Feed::check and serde integer ranges', () => {
    const sessions = (limit: number): Feed => ({ feed: 'sessions', project: 'p', limit });
    const tail = (n: number): Feed => ({ feed: 'transcript', session: 's', tail: n });
    const cards = (n: number): Feed => ({ feed: 'cards', sessions: Array.from({ length: n }, String) });
    for (const ok of [sessions(1), sessions(500), cards(0), cards(64), tail(0), tail(500), { feed: 'live' } as const]) {
      expect(checkFeed(ok)).toBeNull();
    }
    for (const bad of [
      sessions(0),
      sessions(501),
      sessions(-1),
      sessions(2.5),
      sessions(Number.NaN),
      cards(65),
      tail(501),
      tail(-1),
      tail(0.5),
      tail(Number.POSITIVE_INFINITY),
    ]) {
      expect(checkFeed(bad)).not.toBeNull();
    }
  });

  test('requests outside api.rs ranges are refused before sending', () => {
    const ok: Request[] = [
      { id: 0, seq: null, op: { op: 'ping' } },
      { id: Number.MAX_SAFE_INTEGER, seq: 0, op: { op: 'kill', live: { key: 'k', generation: 0 } } },
      { id: 1, seq: null, op: { op: 'detach', view: 0xffff_ffff } },
      { id: 1, seq: 3, op: { op: 'answer', live, request: 0, proceed: true } },
    ];
    for (const request of ok) {
      expect(checkRequest(request)).toBeNull();
      expect(() => requestJson(request)).not.toThrow();
    }
    const bad: Request[] = [
      { id: -1, seq: null, op: { op: 'ping' } },
      { id: 1.5, seq: null, op: { op: 'ping' } },
      { id: 2 ** 53, seq: null, op: { op: 'ping' } },
      { id: 1, seq: -2, op: { op: 'kill', live } },
      { id: 1, seq: 0.5, op: { op: 'kill', live } },
      { id: 1, seq: null, op: { op: 'kill', live } },
      { id: 1, seq: 2, op: { op: 'ping' } },
      { id: 1, seq: null, op: { op: 'outcome', seq: -1 } },
      { id: 1, seq: 4, op: { op: 'cancel', seq: 1.25 } },
      { id: 1, seq: 4, op: { op: 'answer', live, request: -3, proceed: false } },
      { id: 1, seq: null, op: { op: 'detach', view: 2 ** 32 } },
      { id: 1, seq: null, op: { op: 'detach', view: -1 } },
      { id: 1, seq: 2, op: { op: 'stop', live: { key: 'k', generation: -1 } } },
      { id: 1, seq: 2, op: { op: 'stop', live: { key: 'k', generation: 0.5 } } },
      { id: 1, seq: null, op: { op: 'subscribe', feed: { feed: 'transcript', session: 's', tail: -5 } } },
      { id: 1, seq: null, op: { op: 'subscribe', feed: { feed: 'transcript', session: 's', tail: 501 } } },
      { id: 1, seq: null, op: { op: 'subscribe', feed: { feed: 'sessions', project: 'p', limit: 0 } } },
      { id: 1, seq: null, op: { op: 'unsubscribe', feed: { feed: 'sessions', project: 'p', limit: 1.5 } } },
    ];
    for (const request of bad) {
      expect(checkRequest(request)).not.toBeNull();
      expect(() => requestJson(request)).toThrow(ApiRequestError);
      expect(() => requestRecord(request)).toThrow(ApiRequestError);
    }
  });

  test('the builder refuses out-of-range ops without consuming an id or seq', () => {
    const builder = new RequestBuilder({ next_seq: 7 });
    expect(() => builder.build({ op: 'detach', view: -1 })).toThrow(ApiRequestError);
    expect(() => builder.build({ op: 'cancel', seq: 0.5 })).toThrow(ApiRequestError);
    expect(builder.build({ op: 'cancel', seq: 1 })).toEqual({ id: 1, seq: 7, op: { op: 'cancel', seq: 1 } });
  });

  test('builder assigns ids always and seqs exactly for journaled ops', () => {
    const builder = new RequestBuilder({ next_seq: 28 });
    expect(builder.build({ op: 'ping' })).toEqual({ id: 1, seq: null, op: { op: 'ping' } });
    expect(builder.build({ op: 'kill', live })).toEqual({ id: 2, seq: 28, op: { op: 'kill', live } });
    expect(builder.build({ op: 'attach', live, mode: 'control' }).seq).toBeNull();
    expect(builder.build({ op: 'inbox_clear' }).seq).toBe(29);
    expect(builder.nextSeq).toBe(30);
  });
});

describe('gateway messages validate', () => {
  const decoders = {
    reply: decodeReply,
    event: decodeEvent,
    welcome: decodeWelcome,
    term_end: decodeTermEnd,
  } as const;

  for (const type of ['reply', 'event', 'welcome', 'term_end'] as const) {
    for (const vector of messages(type)) {
      test(`${type} ${vector.case}`, () => {
        const value = decoders[type](utf8(vector.json));
        const parsed: unknown = JSON.parse(vector.json);
        expect(parsed).toEqual(value);
        // Same keys in the same order as Rust wrote them.
        expect(JSON.stringify(value)).toBe(JSON.stringify(parsed));
      });
    }
  }

  function expectDecodeError(run: () => unknown): void {
    expect(run).toThrow(ApiDecodeError);
  }

  test('unknown fields are ignored', () => {
    const reply = decodeReply(utf8('{"id":3,"ok":{"type":"accepted","seq":4,"duplicate":false,"new":1},"x":[]}'));
    expect(reply).toEqual({ id: 3, ok: { type: 'accepted', seq: 4, duplicate: false } });
    expect(decodeEvent(utf8('{"type":"resync","since":5}'))).toEqual({ type: 'resync' });
  });

  test('missing optionals read as null; missing required fields are refused', () => {
    expect(decodeTermEnd(utf8('{"reason":"exited"}'))).toEqual({ reason: 'exited', code: null });
    expectDecodeError(() => decodeEvent(utf8('{"type":"term_state","view":1}')));
  });

  test('wrong types, unknown variants and bad shapes are refused', () => {
    const bad: [(b: Uint8Array) => unknown, string][] = [
      [decodeReply, '{"id":"1","ok":{"type":"unit"}}'],
      [decodeReply, '{"id":1}'],
      [decodeReply, '{"id":1,"ok":{"type":"unit"},"err":{"code":"expired"}}'],
      [decodeReply, '{"id":1,"ok":{"type":"teleported"}}'],
      [decodeReply, '{"id":1,"err":{"code":"not_allowed","need":"admin"}}'],
      [decodeReply, '{"id":-1,"ok":{"type":"unit"}}'],
      [decodeReply, '{"id":1.5,"ok":{"type":"unit"}}'],
      [decodeEvent, '{"type":"progress","seq":1,"stage":"x","done":"1","total":null}'],
      [decodeEvent, '{"type":"term_state","view":4294967296,"input_held":false}'],
      [decodeEvent, '[]'],
      [decodeEvent, 'nope'],
      [decodeEvent, '{"type":"outcome","seq":1,"outcome":{"state":"done","result":{"type":"session","live":{"key":1,"generation":1}}}}'],
      [decodeTermEnd, '{"reason":"exited","code":2147483648}'],
      [decodeTermEnd, '{}'],
    ];
    for (const [decode, json] of bad) expectDecodeError(() => decode(utf8(json)));
    expectDecodeError(() => decodeEvent(Uint8Array.of(0xff)));
    // Only a string tag outside the known set is tolerated, not other shapes.
    expectDecodeError(() => decodeEvent(utf8('{"type":7}')));
    expectDecodeError(() => decodeEvent(utf8('{}')));
  });

  test('an unknown event type decodes to an UnknownEvent', () => {
    expect(decodeEvent(utf8('{"type":"hologram","depth":3}'))).toEqual({ type: 'unknown_event', name: 'hologram' });
  });

  test('an unknown transcript item type keeps its place among the items', () => {
    const json =
      '{"type":"feed","feed":{"feed":"transcript","session":"s","agent":null,"tail":3},' +
      '"value":{"feed":"transcript","start":4,"reset":false,"items":[' +
      '{"type":"thinking","text":"a"},{"type":"hologram","x":1},{"type":"exit","reason":"done"}]}}';
    expect(decodeEvent(utf8(json))).toEqual({
      type: 'feed',
      feed: { feed: 'transcript', session: 's', agent: null, tail: 3 },
      value: {
        feed: 'transcript',
        start: 4,
        items: [{ type: 'thinking', text: 'a' }, { type: 'unknown_item', name: 'hologram' }, { type: 'exit', reason: 'done' }],
        reset: false,
      },
    });
    // A malformed known item is still refused.
    expectDecodeError(() =>
      decodeEvent(
        utf8(
          '{"type":"feed","feed":{"feed":"transcript","session":"s","agent":null,"tail":3},' +
            '"value":{"feed":"transcript","start":0,"reset":false,"items":[{"type":"thinking"}]}}',
        ),
      ),
    );
  });

  test('a welcome of any protocol version from 1 up to PROTOCOL is accepted', () => {
    const welcome = messages('welcome')[0]!;
    const at = (version: number) => welcome.json.replace('"protocol":1', `"protocol":${version}`);
    for (let version = 1; version <= PROTOCOL; version++) {
      expect(decodeWelcome(utf8(at(version))).protocol).toBe(version);
    }
    for (const version of [0, PROTOCOL + 1]) {
      expect(at(version)).not.toBe(welcome.json);
      expectDecodeError(() => decodeWelcome(utf8(at(version))));
    }
  });
});
